import assert from 'node:assert/strict';import fs from 'node:fs/promises';import path from 'node:path';
import{loadEnv,preflight}from'../lib/env.mjs';import{createSession}from'../lib/harness.mjs';
const env=await loadEnv();assert.ok(['localhost','127.0.0.1'].includes(new URL(env.api).hostname));await preflight(env);const red=process.env.QA_QUOTATION_BLANK_RED==='1';const output=path.resolve(process.env.QA_QUOTATION_BLANK_OUTPUT_DIR||'qa/2026-10-01_comprehensive-audit_ui35-blank-final');await fs.mkdir(output,{recursive:true});const ctx=await createSession({env,role:'ADMIN',evidenceDir:output,runId:'UI35-BLANK'});const proof={role:ctx.role,account:ctx.username,states:[],writes:[]};const save=async()=>fs.writeFile(path.join(output,'driver-assertions.json'),JSON.stringify({...proof,errors:ctx.errors},null,2)+'\n');
async function reads(){const detail=await ctx.apiGet('/quotations/45');const versions=await ctx.apiGet('/quotations/45/versions');assert.equal(detail.status,200);assert.equal(versions.status,200);return{detail,versions};}
async function capture(label){const shot=await ctx.screenshot(label);const dom=await ctx.page.evaluate(()=>({url:location.pathname,text:document.body.innerText,inputs:[...document.querySelectorAll('.quotation-route-block input')].map(e=>({label:e.getAttribute('aria-label'),value:e.value,rect:e.getBoundingClientRect().toJSON()})),focus:document.activeElement?.getAttribute('aria-label')}));const domPath=shot.replace(/\.png$/,'-dom.json');await fs.writeFile(domPath,JSON.stringify(dom,null,2)+'\n');proof.states.push({label,shot,domPath,dom});await save();}
async function clear(input){await input.click();const n=await input.evaluate(e=>e.value.length);for(let i=0;i<n;i++)await ctx.page.keyboard.press('ArrowRight');for(let i=0;i<n;i++)await ctx.page.keyboard.press('Backspace');assert.equal(await input.evaluate(e=>e.value),'');}
try{await ctx.page.setViewport({width:390,height:900,hasTouch:true});await ctx.page.setRequestInterception(true);ctx.page.on('request',r=>{if(['POST','PUT','PATCH','DELETE'].includes(r.method())){proof.writes.push({method:r.method(),url:r.url(),body:JSON.parse(r.postData()||'{}'),materialWrite:false});void r.abort('blockedbyclient');}else void r.continue();});const before=await reads();proof.before=before;assert.equal(before.versions.body.items[0].version,3);await ctx.goto('/config/quotations');const h=await ctx.page.evaluateHandle(name=>[...document.querySelectorAll('.quotation-frames tbody tr')].find(e=>e.textContent.includes(name)),before.detail.body.templateName);assert.ok(h.asElement());await h.asElement().click();await ctx.page.waitForSelector('.quotation-route-block input');await ctx.settle(200);const input=await ctx.page.$('[aria-label="Hệ số Hải Phòng-NEWEB 1.25T"]');assert.ok(input);assert.equal(await input.evaluate(e=>e.value),'1');await clear(input);await capture('blank-draft');await ctx.page.keyboard.press('Tab');await ctx.settle(400);await capture('blank-blurred');if(red){assert.equal(proof.writes.length,1);assert.equal(proof.writes[0].body.cells.find(c=>c.routeId===1&&c.vehicleSizeClassCode==='1.25T').heSo,0);}else{assert.equal(proof.writes.length,0);assert.equal(await input.evaluate(e=>e.value),'1','Blank blur restores persisted coefficient');await clear(input);await ctx.page.keyboard.type('0');await capture('explicit-zero-draft');await ctx.page.keyboard.press('Tab');await ctx.settle(400);await capture('explicit-zero-blurred');assert.equal(proof.writes.length,1);assert.equal(proof.writes[0].body.cells.find(c=>c.routeId===1&&c.vehicleSizeClassCode==='1.25T').heSo,0);}const after=await reads();assert.deepEqual(after,before);proof.after=after;proof.complete=true;await save();console.log(JSON.stringify({complete:true,redReproduced:red,blankMaterialWrites:0,blankAttemptedWrites:red?1:0,explicitZeroStillValid:!red,blockedWrites:proof.writes.length,version:3}));}finally{await save();await ctx.browser.close();}
